import pytest
from candidate import sum_product


def test_sum_product_normal_case_returns_correct_tuple():
    assert sum_product([1, 2, 3, 4]) == (10, 24)


def test_sum_product_empty_list_returns_zero_and_one():
    assert sum_product([]) == (0, 1)


def test_sum_product_single_element_returns_element_twice():
    assert sum_product([5]) == (5, 5)


def test_sum_product_negative_numbers_returns_correct_sum_and_product():
    assert sum_product([-1, -2]) == (-3, 2)


def test_sum_product_zeros_in_list_returns_zero_product():
    assert sum_product([0, 5]) == (5, 0)


def test_sum_product_all_zeros_returns_zero_tuple():
    assert sum_product([0, 0, 0]) == (0, 0)


def test_sum_product_mixed_signs_returns_correct_values():
    assert sum_product([-1, 2, -3]) == (-2, 6)


def test_sum_product_large_numbers_handles_big_integers():
    assert sum_product([1000000, 2000000]) == (3000000, 2000000000000)


